"        if ibb == \"list\":", "            return cat([\"krt.list_index(\", wrap_list(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ibb == \"froz\":", "            return cat([\"krt.list_index(\", wrap_froz(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ib[t] == \"any\":", "            return cat([\"krt.index(\", emit_expr(st, ib), \", \", ix, \")\"])", "        return cat([\"krt.str_index(\", wrap_str(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "", "    if k == \"slice\":", "        dict sb = e[base]", "        str sx = emit_expr(st, sb)", "        str sfn = \"str_slice\"", "        str recv = wrap_str(sx, sb[t], e_nullable(sb))", "        str sbb = base_type(sb[t])", "        if sbb == \"list\":", "            sfn = \"list_slice\"", "            recv = wrap_list(sx, sb[t], e_nullable(sb))", "        elif sbb == \"froz\":", "            sfn = \"list_slice\"", "            recv = wrap_froz(sx, sb[t], e_nullable(sb))", "        elif sb[t] == \"any\":", "            sfn = \"slice\"", "            recv = sx", "        list sp = [recv]", "        if e[from] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict fr = e[from]", "            sp.add(wrap_flint(emit_expr(st, fr), fr[t], e_nullable(fr)))", "        if e[to] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict tto = e[to]", "            sp.add(wrap_flint(emit_expr(st, tto), tto[t], e_nullable(tto)))", "        if NOT (e[step] is NONE):", "            dict stp = e[step]", "            sp.add(wrap_flint(emit_expr(st, stp), stp[t], e_nullable(stp)))", "        return cat([\"krt.\", sfn, \"(\", sp.join(\", \"), \")\"])", "", "    if k == \"method\":", "        dict mb = e[base]", "        str mx = emit_expr(st, mb)", "        str mrecv = wrap_str(mx, mb[t], e_nullable(mb))", "        str mbb = base_type(mb[t])", "        if mbb == \"list\":", "            mrecv = wrap_list(mx, mb[t], e_n