ble(bna)), \" * \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"/\":", "            return cat([\"krt.div(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"//\":", "            return cat([\"krt.idiv(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"%\":", "            return cat([\"krt.mod(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"**\":", "            return cat([\"krt.pow(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"==\":", "            return cat([\"(\", xa, \" == \", xb, \")\"])", "        if op == \"!=\":", "            return cat([\"(\", xa, \" ~= \", xb, \")\"])", "        if op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\":", "            if bna[t] == \"any\" OR bnb[t] == \"any\":", "                str cfn = \"lt\"", "                if op == \"<=\":", "                    cfn = \"le\"", "                elif op == \">\":", "                    cfn = \"gt\"", "                elif op == \">=\":", "                    cfn = \"ge\"", "                return cat([\"krt.\", cfn, \"(\", xa, \", \", xb, \")\"])", "            return cat([\"(\", ordered_x(xa, bna, bnb), \" \", op, \" \", ordered_x(xb, bnb, bna), \")\"])", "        if op == \"AND\":", "            return cat([\"(krt.truthy_strict(\", xa, \") and krt.truthy_strict(\", xb, \"))\"])", "        if op == \"OR\":", "            return cat([\"(krt.truthy_strict(\", xa, \") or krt.truthy_strict(\", xb, \"))\"])", "        return \"krt.NONE\"", "", "    if k == \"chain\":", "        list cops = e[ops]", "        list coper = e[operands]", "        list clines = []", "        list cconds = []", "        dict cprev_node = coper[0]", "        str cprev = emit_expr(st, cp