at([clines.join(\"; \"), \"; \"])", "        return cat([\"(function() \", cpre, \"return \", cconds.join(\" and \"), \" end)()\"])", "", "    return \"krt.NONE\"", "", "# Объявления поднимаются в начало своей функции (D11, D43).", "func collect_walk(list stmts, list out) -> list:", "    for s0 in stmts:", "        dict s = s0", "        str sk = s[k]", "        if sk == \"decl\":", "            out.add(s[lua])", "        elif sk == \"import\" OR sk == \"namespace\":", "            collect_walk(s[body], out)", "        elif sk == \"if\":", "            list brs = s[branches]", "            for b0 in brs:", "                dict b = b0", "                collect_walk(b[body], out)", "            if s.contains(\"else_body\"):", "                collect_walk(s[else_body], out)", "        elif sk == \"while\" OR sk == \"for\" OR sk == \"for_in\":", "            collect_walk(s[body], out)", "        elif sk == \"try\":", "            collect_walk(s[body], out)", "            for h0 in s[triggers]:", "                dict h = h0", "                collect_walk(h[body], out)", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                collect_walk(ha[body], out)", "            collect_walk(s[\"finally\"], out)", "    return out", "", "func collect_scope(list stmts) -> list:", "    list out = []", "    collect_walk(stmts, out)", "    return out", "", "func emit_hoist(dict st, list names):", "    if len(names) == 0:", "        return:", "    list lua = []", "    list nones = []", "    for n0 in names:", "        str n = n0", "        lua.add(n)", "        nones.add(\"krt.NONE\")", "    emit_line(st, cat([\"local \", lua.join(\", \"), \" = \", nones.join(\", \")]))", "", "func lua_str_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = \", lua_str(d.take(k))]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func lua_true_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = true\"]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func cat_lists(list a, list b) -> list:", "    list out = []", "    for x in a:", "        out.add(x)", "    for y in b:", "        out.add(y)", "    return out", "", "func lua_str_list(list xs) -> str:", "    list parts = []", "    for x in xs:", "        parts.add(lua_str(x))", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "# Стейтменты -> строки Lua. Рекурсивна только сама в себя.", "func emit_stmts(dict st, list stmts) -> str:", "    flint i = 0", "    while i < len(stmts):", "        dict s = stmts[i]", "        dict saved = st[cur_pos]", "        st.add(\"cur_pos\", stmt_pos(s))", "        str sk = s[k]", "        bool wrap_ret = FALSE", "        if sk == \"import\" OR sk == \"namespace\":", "            emit_stmts(st, s[body])", "        if sk == \"return\" AND i < len(stmts) - 1:", "            wrap_ret = TRUE", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "        if sk == \"model\":", "            dict msc = s[schema]", "            str mn2 = s[name]", "            dict msc_mf = msc[model_fields]", "            dict msc_ft = msc[field_types]", "            dict msc_cs = msc[consts]", "            dict msc_if = msc[init_fields]", "            dict msc_pt = msc[param_types]", "            list msc_ord = msc[order]", "            list msc_fo = msc[field_order]", "            list msc_pl = msc[params]", "            list msc_all = msc_fo", "            emit_line(st, cat([\"krt.model_define(\", lua_str(mn2), \", \", lua_str_map_keys(msc_mf, msc_ord), \", \", lua_str_map_keys(msc_ft, msc_all), \", \", lua_true_map_keys(msc_cs, msc_all), \", \", lua_true_map_keys(msc_if, msc_fo), \", \", lua_str_list(msc_pl), \", \", lua_str_map_keys(msc_pt, msc_pl), \")\"]))", "            list mflds = s[fields]", "            for mf0 in mflds:", "                dict mfn2 = mf0", "                dict mfe = mfn2[expr]", "                str mfx = coerce_to(emit_expr(st, mfe), mfe[t], mfn2[type])", "                emit_line(st, cat([\"krt.model_set_value(\", lua_str(mn2), \", \", lua_str(mfn2[name]), \", \", mfx, \")\"]))", "            dict mcons2 = msc[ctor]", "            list mcps = mcons2[params]", "            list mcpl = [\"self\"]", "            for mcp0 in mcps:", "                dict mcp = mcp0", "                mcpl.add(mcp[lua])", "            emit_line(st, cat([\"krt.model_construct(\", lua_str(mn2), \", function(\", mcpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            str msv = st[current_ret]", "            st.add(\"current_ret\", \"NONE\")", "            list mcbody = mcons2[body]", "            emit_hoist(st, collect_scope(mcbody))", "            emit_stmts(st, mcbody)", "            st.add(\"current_ret\", msv)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            list mmorder = msc[method_order]", "            for mmn2 in mmorder:", "                dict msmeth6 = msc[methods]", "                dict mmi2 = msmeth6.take(mmn2)", "                list mmps = [ \"self\" ]", "                list mmpl = mmi2[params]", "                for mmp0 in mmpl:", "                    dict mmp = mmp0", "                    mmps.add(mmp[lua])", "                emit_line(st, cat([\"krt.model_method(\", lua_str(mn2), \", \", lua_str(mmn2), \", function(\", mmps.join(\", \"), \")\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str msv2 = st[current_ret]", "                st.add(\"current_ret\", mmi2[ret])", "                list mmbody = mmi2[body]", "                emit_hoist(st, collect_scope(mmbody))", "                emit_stmts(st, mmbody)", "                st.add(\"current_ret\", msv2)", "                bool mmend = FALSE", "                if len(mmbody) > 0:", "                    dict mmlast = mmbody[len(mmbody) - 1]", "                    if mmlast[k] == \"return\":", "                        mmend = TRUE", "                if NOT mmend:", "                    emit_line(st, \"return krt.NONE\")", "                st.add(\"indent\", st[indent] - 1)", "                emit_line(st, \"end)\")", "        elif sk == \"self_init\":", "            list sfl = s[fields]", "            for sf0 in sfl:", "                dict sf = sf0", "                emit_line(st, cat([\"krt.model_create_field(self, \", lua_str(sf[name]), \", \", sf[lua], \", \", \"false\", \", \", lua_str(sf[type]), \")\"]))", "        elif sk == \"field_create\":", "            dict fce = s[expr]", "            str fcx = checked(emit_expr(st, fce), fce[t], e_nullable(fce), s[type])", "            str fcb = emit_expr(st, s[base])", "            str fcc = \"false\"", "            if is_const_name(s[name]):", "                fcc = \"true\"", "            emit_line(st, cat([\"krt.model_create_field(\", fcb, \", \", lua_str(s[name]), \", \", fcx, \", \", fcc, \", \", lua_str(s[type]), \")\"]))", "        elif sk == \"field_assign\":", "            dict fae = s[expr]", "            str fax = checked(emit_expr(st, fae), fae[t], e_nullable(fae), s[type])", "            emit_line(st, cat([\"krt.model_set(\", emit_expr(st, s[base]), \", \", lua_str(s[name]), \", \", fax, \")\"]))", "        elif sk == \"decl\":", "            dict de = s[expr]", "            str dx = checked(emit_expr(st, de), de[t], e_nullable(de), s[type])", "            if de[t] != \"NONE\":", "                dx = typed_wrap(dx, s[type])", "            emit_line(st, cat([s[lua], \" = \", dx]))", "        elif sk == \"assign\":", "            dict ae = s[expr]", "            str ax = checked(emit_expr(st, ae), ae[t], e_nullable(ae), s[type])", "            if ae[t] != \"NONE\":", "                ax = typed_wrap(ax, s[type])", "            emit_line(st, cat([s[lua], \" = \", ax]))", "        elif sk == \"compound\":", "            dict ce = s[expr]", "            str lhs = wrap_flint(s[lua], \"flint\", s[nullable])", "            str rhs = wrap_flint(emit_expr(st, ce), ce[t], e_nullable(ce))", "            str cop = s[op]", "            str ex = \"\"", "            if cop == \"+\":", "                ex = cat([\"(\", lhs, \" + \", rhs, \")\"])", "            elif cop == \"-\":", "                ex = cat([\"(\", lhs, \" - \", rhs, \")\"])", "            elif cop == \"*\":", "                ex = cat([\"(\", lhs, \" * \", rhs, \")\"])", "            elif cop == \"/\":", "                ex = cat([\"krt.div(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"//\":", "                ex = cat([\"krt.idiv(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"%\":", "                ex = cat([\"krt.mod(\", lhs, \", \", rhs, \")\"])", "            else:", "                ex = cat([\"krt.pow(\", lhs, \", \", rhs, \")\"])", "            emit_line(st, cat([s[lua], \" = \", ex]))", "        elif sk == \"setindex\":", "            dict tg = s[target]", "            dict tv = s[expr]", "            str tvx = emit_expr(st, tv)", "            if tg[k] == \"dget\":", "                dict tb = tg[base]", "                str tdx = wrap_dict(emit_expr(st, tb), tb[t], e_nullable(tb))", "                str rawtk = str(tg[key])", "                str tdk = \"\"", "                if tg[ktype] == \"flint\":", "                    tdk = rawtk", "                else:", "                    tdk = lua_str(rawtk)", "                emit_line(st, cat([\"krt.dict_set(\", tdx, \", \", tdk, \", \", tvx, \")\"]))", "            else:", "                dict tib = tg[base]", "                dict tii = tg[index]", "                str tbx = emit_expr(st, tib)", "                str tix = wrap_flint(emit_expr(st, tii), tii[t], e_nullable(tii))", "                str tibb = base_type(tib[t])", "                if tibb == \"list\" OR tibb == \"froz\":", "                    str tbx2 = \"\"", "                    if tibb == \"froz\":", "                        tbx2 = wrap_froz(tbx, tib[t], e_nullable(tib))", "                    else:", "                        tbx2 = wrap_list(tbx, tib[t], e_nullable(tib))", "                    emit_line(st, cat([\"krt.list_replace(\", tbx2, \", \", tix, \", \", tvx, \")\"]))", "                else:", "                    emit_line(st, cat([\"krt.index_set(\", tbx, \", \", tix, \", \", tvx, \")\"]))", "        elif sk == \"panic\":", "            emit_line(st, cat([\"krt.fail(\", lua_str(s[cat]), \", \", lua_str(s[msg]), \")\"]))", "        elif sk == \"exprstmt\":", "            emit_line(st, emit_expr(st, s[expr]))", "        elif sk == \"if\":", "            list brs = s[branches]", "            flint bi = 0", "            while bi < len(brs):", "                dict br = brs[bi]", "                dict bc = br[cond]", "                str kw = \"elseif\"", "                if bi == 0:", "                    kw = \"if\"", "                emit_line(st, cat([kw, \" krt.truthy_strict(\", emit_expr(st, bc), \") then\"]))", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, br[body])", "                st.add(\"indent\", st[indent] - 1)", "                bi += 1", "            if s.contains(\"else_body\"):", "                emit_line(st, \"else\")", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, s[else_body])", "                st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"try\":", "            st.add(\"try_id\", st[try_id] + 1)", "            str tid = str(st[try_id])", "            str tnorm = cat([\"__try_normal_\", tid])", "            str tok2 = cat([\"__try_ok_\", tid])", "            str tval2 = cat([\"__try_val_\", tid])", "            str terr2 = cat([\"__try_err_\", tid])", "            str thok = cat([\"__try_hok_\", tid])", "            str hval2 = cat([\"__try_hval_\", tid])", "            str thandled = cat([\"__try_handled_\", tid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local \", tnorm, \" = \\{\\}\"]))", "            emit_line(st, cat([\"local \", tok2, \", \", tval2]))", "            emit_line(st, cat([tok2, \", \", tval2, \" = pcall(function()\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"return \", tnorm]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            emit_line(st, cat([\"if not \", tok2, \" then\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local \", terr2, \" = \", tval2]))", "            emit_line(st, cat([\"local \", thok, \", \", hval2]))", "            emit_line(st, cat([thok, \", \", hval2, \" = pcall(function()\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local error = krt.error_new(\", terr2, \")\"]))", "            emit_line(st, cat([\"local \", thandled, \" = false\"]))", "            bool zfirst = TRUE", "            for h0 in s[triggers]:", "                dict h = h0", "                str zkw = \"if\"", "                if NOT zfirst:", "                    zkw = \"elseif\"", "                str zcond = cat([\"error.cat == \", lua_str(h[cat])])", "                if h.contains(\"cats\"):", "                    list zcnames = h[cats]", "                    list zparts = []", "                    flint zpi = 0", "                    while zpi < len(zcnames):", "                        zparts.add(cat([\"error.cat == \", lua_str(zcnames[zpi])]))", "                        zpi += 1", "                    zcond = zparts.join(\" or \")", "                emit_line(st, cat([zkw, \" \", zcond, \" then\"]))", "                st.add(\"indent\", st[indent] + 1)", "                emit_line(st, cat([thandled, \" = true\"]))", "                emit_stmts(st, h[body])", "                st.add(\"indent\", st[indent] - 1)", "                zfirst = FALSE", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                if zfirst:", "                    emit_line(st, \"if true then\")", "                else:", "                    emit_line(st, \"else\")", "                st.add(\"indent\", st[indent] + 1)", "                emit_line(st, cat([thandled, \" = true\"]))", "                emit_stmts(st, ha[body])", "                st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"if not \", thandled, \" then _G.error(\", terr2, \", 0) end\"]))", "            emit_line(st, cat([\"return \", tnorm]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            emit_line(st, cat([tok2, \", \", tval2, \" = \", thok, \", \", hval2]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_stmts(st, s[\"finally\"])", "            emit_line(st, cat([\"if not \", tok2, \" then _G.error(\", tval2, \", 0) end\"]))", "            emit_line(st, cat([\"if \", tval2, \" ~= \", tnorm, \" then return \", tval2, \" end\"]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"while\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str lid = str(st[loop_id])", "            str cont = cat([\"__continue_\", lid])", "            str brk = cat([\"__break_\", lid])", "            dict wc2 = s[cond]", "            emit_line(st, cat([\"while krt.truthy_strict(\", emit_expr(st, wc2), \") do\"]))", "            st.add(\"indent\", st[indent] + 1)", "            list ls = st[loop_stack]", "            ls.add({cont: cont, brk: brk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", cont, \"::\"]))", "            ls.del(len(ls) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", brk, \"::\"]))", "        elif sk == \"break\":", "            list lsb = st[loop_stack]", "            dict topb = lsb[len(lsb) - 1]", "            emit_line(st, cat([\"goto \", topb[brk]]))", "        elif sk == \"continue\":", "            list lsc = st[loop_stack]", "            dict topc = lsc[len(lsc) - 1]", "            emit_line(st, cat([\"goto \", topc[cont]]))", "        elif sk == \"for\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str fid = str(st[loop_id])", "            str fcont = cat([\"__continue_\", fid])", "            str fbrk = cat([\"__break_\", fid])", "            str fv = s[lua]", "            if s.contains(\"float_fmt\"):", "                dict range_names = st[range_floats]", "                if range_names is NONE:", "                    range_names = {}", "                range_names.add(fv, TRUE)", "                st.add(\"range_floats\", range_names)", "            str fto = cat([\"__to_\", fid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            str form = s[form]", "            if form == \"upto\":", "                emit_line(st, cat([\"local \", fv, \" = 0\"]))", "                dict fte = s[to]", "                emit_line(st, cat([\"local \", fto, \" = \", wrap_flint(emit_expr(st, fte), fte[t], e_nullable(fte))]))", "                emit_line(st, cat([\"while \", fv, \" < \", fto, \" do\"]))", "            else:", "                dict ffe = s[from]", "                dict ftte = s[to]", "                str fstep = cat([\"__step_\", fid])", "                emit_line(st, cat([\"local \", fv, \" = \", wrap_flint(emit_expr(st, ffe), ffe[t], e_nullable(ffe))]))", "                emit_line(st, cat([\"local \", fto, \" = \", wrap_flint(emit_expr(st, ftte), ftte[t], e_nullable(ftte))]))", "                str sx = \"1\"", "                if s.contains(\"step\"):", "                    dict fse = s[step]", "                    sx = wrap_flint(emit_expr(st, fse), fse[t], e_nullable(fse))", "                emit_line(st, cat([\"local \", fstep, \" = \", sx]))", "                emit_line(st, cat([\"while ((\", fstep, \" > 0) and (\", fv, \" < \", fto, \")) or ((\", fstep, \" < 0) and (\", fv, \" > \", fto, \")) do\"]))", "            st.add(\"indent\", st[indent] + 1)", "            list fls = st[loop_stack]", "            fls.add({cont: fcont, brk: fbrk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", fcont, \"::\"]))", "            if form == \"upto\":", "                emit_line(st, cat([fv, \" = \", fv, \" + 1\"]))", "            else:", "                emit_line(st, cat([fv, \" = \", fv, \" + __step_\", fid]))", "            fls.del(len(fls) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", fbrk, \"::\"]))", "        elif sk == \"for_in\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str iid = str(st[loop_id])", "            str icont = cat([\"__continue_\", iid])", "            str ibrk = cat([\"__break_\", iid])", "            str icoll = cat([\"__coll_\", iid])", "            str iidx = cat([\"__i_\", iid])", "            dict ice = s[coll]", "            list inames = s[names]", "            list ilnames = s[lnames]", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            bool list_mode = FALSE", "            str iceb = base_type(ice[t])", "            if iceb == \"list\" OR iceb == \"froz\":", "                list_mode = TRUE", "